"// Mapping logic to generate the familiyName according to the following convention.
// B	van den Boele
// BP	van den Boele – de Vries
// P	de Vries
// PB   de Vries – van den Boele
function generatefamiliyName() {
    let nickName = Person.Name.NickName;
    let middleName = Person.Name.FamilyNamePrefix;
    let lastName = Person.Name.FamilyName;
    let middleNamePartner = Person.Name.FamilyNamePartnerPrefix;
    let lastNamePartner = Person.Name.FamilyNamePartner;
    let convention = Person.Name.Convention;

    let familiyName = '';
    switch (convention) {
        case "BP":
            if (typeof middleName !== 'undefined' && middleName) { familiyName = familiyName + middleName + ' ' }
            familiyName = familiyName + lastName;

            familiyName = familiyName + ' - ';
            if (typeof middleNamePartner !== 'undefined' && middleNamePartner) { familiyName = familiyName + middleNamePartner + ' ' }
            familiyName = familiyName + lastNamePartner;
            break;
        case "PB":
            if (typeof middleNamePartner !== 'undefined' && middleNamePartner) { familiyName = familiyName + middleNamePartner + ' ' }
            familiyName = familiyName + lastNamePartner;

            familiyName = familiyName + ' - ';
            if (typeof middleName !== 'undefined' && middleName) { familiyName = familiyName + middleName + ' ' }
            familiyName = familiyName + lastName;
            break;
        case "P":
            if (typeof middleNamePartner !== 'undefined' && middleNamePartner) { familiyName = familiyName + middleNamePartner + ' ' }
            familiyName = familiyName + lastNamePartner;
            break;
        case "B":
        default:
            if (typeof middleName !== 'undefined' && middleName) { familiyName = familiyName + middleName + ' ' }
            familiyName = familiyName + lastName;
            break;
    }
    // Trim spaces at start and end
    familiyName = familiyName.trim();


    return familiyName
}

